mapper.update:
UPDATE xsy_mall_page
SET title = #{title}, draft_content = #{content}, version = version + 1,
    updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE page_code = #{pageCode}
    AND version = #{version}

UPDATE xsy_mall_page
SET published_content = draft_content, published_title = title, published_version = version,
    published_at = CURRENT_TIMESTAMP, published_by = #{operator}
WHERE page_code = #{pageCode}
    AND version = #{version}

UPDATE xsy_mall_store
SET store_name = #{storeName}, store_link = #{storeLink}, version = version + 1,
    updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = 1
    AND version = #{version}
